  match value with
  | `Queued -> "queued"
  | `Running -> "running"
  | `Streaming -> "streaming"
  | `Pushed -> "pushed"
  | `PrOpen -> "pr_open"
  | `PrMerged -> "pr_merged"
  | `PrClosed -> "pr_closed"
  | `Done -> "done"
  | `Failed -> "failed"
  | `Cancelled -> "cancelled"

