  match value with
  | "queued" -> Ok `Queued
  | "running" -> Ok `Running
  | "streaming" -> Ok `Streaming
  | "pushed" -> Ok `Pushed
  | "pr_open" -> Ok `PrOpen
  | "pr_merged" -> Ok `PrMerged
  | "pr_closed" -> Ok `PrClosed
  | "done" -> Ok `Done
  | "failed" -> Ok `Failed
  | "cancelled" -> Ok `Cancelled
  | _ -> Error ("unsupported agent_remote_dev_tasks.status: " ^ value)

