type workflow_step_runs_status = [ `Running | `Succeeded | `Failed ]

let workflow_step_runs_status_to_string (value : workflow_step_runs_status) : string =
  match value with
  | `Running -> "running"
  | `Succeeded -> "succeeded"
  | `Failed -> "failed"

let parse_workflow_step_runs_status (value : string) : (workflow_step_runs_status, string) result =
  match value with
  | "running" -> Ok `Running
  | "succeeded" -> Ok `Succeeded
  | "failed" -> Ok `Failed
  | _ -> Error ("unsupported workflow_step_runs.status: " ^ value)

type workflow_step_runs_row = {
  workflow_step_runs_id : string;
  workflow_step_runs_run_id : string;
  workflow_step_runs_step_index : int;
  workflow_step_runs_step_name : string;
  workflow_step_runs_step_type : string;
  workflow_step_runs_function_ref : string;
  workflow_step_runs_attempt : int;
  workflow_step_runs_status : string;
  workflow_step_runs_input : string option;
  workflow_step_runs_output : string option;
  workflow_step_runs_error : string option;
  workflow_step_runs_duration_ms : int option;
  workflow_step_runs_started_at : string;
  workflow_step_runs_finished_at : string option;
}

let workflow_step_runs_row_of_row ~(get : int -> string) ~(is_null : int -> bool) : workflow_step_runs_row =
  {
    workflow_step_runs_id = get 0;
    workflow_step_runs_run_id = get 1;
    workflow_step_runs_step_index = int_of_string (get 2);
    workflow_step_runs_step_name = get 3;
    workflow_step_runs_step_type = get 4;
    workflow_step_runs_function_ref = get 5;
    workflow_step_runs_attempt = int_of_string (get 6);
    workflow_step_runs_status = get 7;
    workflow_step_runs_input = (if is_null 8 then None else Some (get 8));
    workflow_step_runs_output = (if is_null 9 then None else Some (get 9));
    workflow_step_runs_error = (if is_null 10 then None else Some (get 10));
    workflow_step_runs_duration_ms = (if is_null 11 then None else Some (int_of_string (get 11)));
    workflow_step_runs_started_at = get 12;
    workflow_step_runs_finished_at = (if is_null 13 then None else Some (get 13));
  }

