let presence_events_select_sql = "select\n      seq,\n      to_char(event_at at time zone 'utc', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"') as event_at,\n      op,\n      conv_id::text as conv_id,\n      user_id::text as user_id,\n      conv_slug,\n      user_slug,\n      conv_shard,\n      user_shard,\n      soft_deleted\n    from presence_events"

type presence_events_op = [ `INSERT | `UPDATE | `DELETE ]

let presence_events_op_to_string (value : presence_events_op) : string =
  match value with
  | `INSERT -> "INSERT"
  | `UPDATE -> "UPDATE"
  | `DELETE -> "DELETE"

let parse_presence_events_op (value : string) : (presence_events_op, string) result =
  match value with
  | "INSERT" -> Ok `INSERT
  | "UPDATE" -> Ok `UPDATE
  | "DELETE" -> Ok `DELETE
  | _ -> Error ("unsupported presence_events.op: " ^ value)

type presence_events_row = {
  presence_events_seq : int64;
  presence_events_event_at : string;
  presence_events_op : string;
  presence_events_conv_id : string;
  presence_events_user_id : string;
  presence_events_conv_slug : string;
  presence_events_user_slug : string;
  presence_events_conv_shard : int;
  presence_events_user_shard : int;
  presence_events_soft_deleted : bool;
}

let presence_events_row_of_row ~(get : int -> string) ~is_null:(_ : int -> bool) : presence_events_row =
  {
    presence_events_seq = Int64.of_string (get 0);
    presence_events_event_at = get 1;
    presence_events_op = get 2;
    presence_events_conv_id = get 3;
    presence_events_user_id = get 4;
    presence_events_conv_slug = get 5;
    presence_events_user_slug = get 6;
    presence_events_conv_shard = int_of_string (get 7);
    presence_events_user_shard = int_of_string (get 8);
    presence_events_soft_deleted = (get 9 = "t");
  }

