  benefactor_marketing_time_entries_entry_date : string;
  benefactor_marketing_time_entries_minutes : int;
  benefactor_marketing_time_entries_billable : bool;
  benefactor_marketing_time_entries_rate_cents : int;
  benefactor_marketing_time_entries_cost_cents : int;
  benefactor_marketing_time_entries_notes : string option;
