    benefactor_marketing_time_entries_campaign_id = (if is_null 2 then None else Some (get 2));
    benefactor_marketing_time_entries_project_task_id = (if is_null 3 then None else Some (get 3));
    benefactor_marketing_time_entries_user_id = get 4;
    benefactor_marketing_time_entries_entry_date = get 5;
    benefactor_marketing_time_entries_minutes = int_of_string (get 6);
    benefactor_marketing_time_entries_billable = (get 7 = "t");
    benefactor_marketing_time_entries_rate_cents = int_of_string (get 8);
    benefactor_marketing_time_entries_cost_cents = int_of_string (get 9);
    benefactor_marketing_time_entries_notes = (if is_null 10 then None else Some (get 10));
    benefactor_marketing_time_entries_meta_data = get 11;
