type benefactor_scrape_queries_query_variant = [ `EmailContact | `ContactUs | `WebsiteDomain | `FuzzyEmail | `FuzzyCity ]

let benefactor_scrape_queries_query_variant_to_string (value : benefactor_scrape_queries_query_variant) : string =
  match value with
  | `EmailContact -> "email_contact"
  | `ContactUs -> "contact_us"
  | `WebsiteDomain -> "website_domain"
  | `FuzzyEmail -> "fuzzy_email"
  | `FuzzyCity -> "fuzzy_city"

let parse_benefactor_scrape_queries_query_variant (value : string) : (benefactor_scrape_queries_query_variant, string) result =
  match value with
  | "email_contact" -> Ok `EmailContact
  | "contact_us" -> Ok `ContactUs
  | "website_domain" -> Ok `WebsiteDomain
  | "fuzzy_email" -> Ok `FuzzyEmail
  | "fuzzy_city" -> Ok `FuzzyCity
  | _ -> Error ("unsupported benefactor_scrape_queries.query_variant: " ^ value)

