let vcs_repositories_table = "vcs_repositories"

let vcs_repositories_columns = ["id"; "slug"; "display_name"; "vcs_kind"; "remote_url"; "default_branch"; "mirror_path"; "mirror_status"; "visibility"; "last_synced_at"; "last_error"; "size_bytes"; "ref_count"; "meta_data"; "is_soft_deleted"; "created_at"; "updated_at"; "created_by"; "updated_by"]

let vcs_repositories_select_sql = "select\n      id::text as id,\n      slug,\n      display_name,\n      vcs_kind,\n      remote_url,\n      default_branch,\n      mirror_path,\n      mirror_status,\n      visibility,\n      to_char(last_synced_at at time zone 'utc', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"') as last_synced_at,\n      last_error,\n      size_bytes,\n      ref_count,\n      meta_data::text as meta_data_json,\n      is_soft_deleted,\n      to_char(created_at at time zone 'utc', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"') as created_at,\n      to_char(updated_at at time zone 'utc', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"') as updated_at,\n      created_by::text as created_by,\n      updated_by::text as updated_by\n    from vcs_repositories"

type vcs_repositories_vcs_kind = [ `Git | `Hg | `Svn | `Fossil ]

let vcs_repositories_vcs_kind_to_string (value : vcs_repositories_vcs_kind) : string =
  match value with
  | `Git -> "git"
  | `Hg -> "hg"
  | `Svn -> "svn"
  | `Fossil -> "fossil"

let parse_vcs_repositories_vcs_kind (value : string) : (vcs_repositories_vcs_kind, string) result =
  match value with
  | "git" -> Ok `Git
  | "hg" -> Ok `Hg
  | "svn" -> Ok `Svn
  | "fossil" -> Ok `Fossil
  | _ -> Error ("unsupported vcs_repositories.vcs_kind: " ^ value)

type vcs_repositories_mirror_status = [ `Pending | `Mirroring | `Ready | `Error | `Disabled ]

